    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$RealDirectory,
        [Parameter(Mandatory = $true)][string]$VirtualDirectory,
        [Parameter(Mandatory = $true)][int]$Depth,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][hashtable]$State
    )
    # A directory whose Depth has reached MaxDepth is not enumerated and earns
    # one 'too_deep' entry. The scan root itself (Depth 0) is always
    # enumerated, so -MaxDepth 0 (and any negative value, clamped to 0) still
    # registers the root's direct children and flags the directories among
    # them with 'too_deep'.
    if ($Depth -ge 1 -and $Depth -ge $State.MaxDepth) {
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'too_deep' `
            -Message "Depth limit of $($State.MaxDepth) reached; not enumerating."
        return
    }

    $children = @()
    try {
        $children = @(Get-ChildItem -LiteralPath $RealDirectory -Force -ErrorAction Stop)
    }
    catch [System.UnauthorizedAccessException] {
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'access_denied' `
            -Message 'Access denied while enumerating the directory.'
        return
    }
    catch {
        # Failure isolation: one unreadable directory must not abort the scan.
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'access_denied' `
            -Message $_.Exception.Message
        return
    }

    foreach ($child in $children) {
        $childDepth = $Depth + 1
        $realChild = [string](Get-WReparseMemberValue -InputObject $child -Name 'FullName')
        $virtualChild = Join-Path $VirtualDirectory (Split-Path -Leaf $realChild)
        $relative = Get-WReparseRelativePath -FullPath $virtualChild -Root $State.Root

        if (Test-WReparseIsReparsePoint -Item $child) {
            $linkType = [string](Get-WReparseMemberValue -InputObject $child -Name 'LinkType')
            $rawTarget = ConvertTo-WReparseTargetString -RawTargetValue (Get-WReparseMemberValue -InputObject $child -Name 'Target')
            $resolved = Resolve-WReparseLinkTarget -LinkFullPath $realChild -RawTarget $rawTarget
            $inScope = $false
            if ($null -ne $resolved) {
                $inScope = Test-WReparseWithinRoot -Path $resolved -Root $State.Root
            }
            [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind 'ReparsePoint' `
                -ReparseKind (Get-WReparseKindFromLinkType -LinkType $linkType) `
                -Target $rawTarget -ResolvedTarget $resolved -InScope $inScope `
                -Depth $childDepth -Size 0))

            if (-not $State.Follow) {
                # Default mode: register the entry only, never enter its
                # target, and never report cycle/broken_target.
                $State.Skipped++
                continue
            }
            if ($null -eq $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target could not be resolved.'
                continue
            }
            if (-not (Test-Path -LiteralPath $resolved)) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target does not exist.'
                continue
            }
            $isCycle = $false
            foreach ($ancestor in $Ancestry) {
                if ([System.StringComparer]::OrdinalIgnoreCase.Equals($ancestor, $resolved)) {
                    $isCycle = $true
                    break
                }
            }
            if ($isCycle) {
                # Only an ANCESTOR on the current branch closes a cycle; two
                # sibling links pointing at the same target do not.
                Add-WReparseError -State $State -RelativePath $relative -Code 'cycle' `
                    -Message 'The reparse target is an ancestor already visited on this branch.'
                continue
            }
            if (Test-Path -LiteralPath $resolved -PathType Container) {
                # Entries below the link are named with the LINK path as
                # prefix (e.g. 'link-in\readme.txt'), not the real target
                # path.
                Invoke-WReparseDirectoryWalk -RealDirectory $resolved -VirtualDirectory $virtualChild `
                    -Depth $childDepth -Ancestry ($Ancestry + $resolved) -State $State
            }
            # A link whose target is a file produces no children.
            continue
        }

        $isContainer = [bool](Get-WReparseMemberValue -InputObject $child -Name 'PSIsContainer')
        $size = [long]0
        if (-not $isContainer) {
            $length = Get-WReparseMemberValue -InputObject $child -Name 'Length'
            if ($null -ne $length) { $size = [long]$length }
        }
        $kind = if ($isContainer) { 'Directory' } else { 'File' }
        # InScope is meaningful for reparse entries only; plain files and
        # directories always report $false.
        [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind $kind `
            -Depth $childDepth -Size $size))

        if ($isContainer) {
            $realChildCanonical = Get-WReparseCanonicalPath $realChild
            Invoke-WReparseDirectoryWalk -RealDirectory $realChildCanonical -VirtualDirectory $virtualChild `
                -Depth $childDepth -Ancestry ($Ancestry + $realChildCanonical) -State $State
        }
    }
}

function Invoke-WReparseWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$Root,
        [ValidateSet('Never', 'Always')][string]$FollowMode = 'Never',
        [int]$MaxDepth = 32
    )
    # A negative depth limit behaves exactly like 0.
    if ($MaxDepth -lt 0) { $MaxDepth = 0 }

    $state = @{
        Records  = New-Object System.Collections.ArrayList
        Errors   = New-Object System.Collections.ArrayList
        Skipped  = 0
        Root     = $null
        Follow   = ($FollowMode -eq 'Always')
        MaxDepth = $MaxDepth
    }

    $canonicalRoot = $null
    try { $canonicalRoot = Get-WReparseCanonicalPath $Root }
    catch {
        return [pscustomobject]@{
            Records = @()
            Errors  = @((New-WReparseError -RelativePath '.' -Code 'invalid_argument' `
                -Message "Scan root cannot be canonicalised: $Root"))
            Skipped = 0
        }
    }

    if (-not (Test-Path -LiteralPath $canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'not_found' `
            -Message "Scan root does not exist: $canonicalRoot"
        return [pscustomobject]@{ Records = @(); Errors = $state.Errors.ToArray(); Skipped = 0 }
    }
    if (-not (Test-Path -LiteralPath $canonicalRoot -PathType Container)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'structure' `
            -Message "Scan root is not a directory: $canonicalRoot"
        return [pscustomobject]@{ Records = @(); Errors = $state.Errors.ToArray(); Skipped = 0 }
    }

    $state.Root = $canonicalRoot
    Invoke-WReparseDirectoryWalk -RealDirectory $canonicalRoot -VirtualDirectory $canonicalRoot `
        -Depth 0 -Ancestry @($canonicalRoot) -State $state

    return [pscustomobject]@{
        Records = $state.Records.ToArray()
        Errors  = $state.Errors.ToArray()
        Skipped = $state.Skipped
    }
}

# WReparse - report assembly
# Deterministic ordering, statistics and serialisation.
# Part of the WReparse implementation. See the contract under docs/

# Stable merge sort so the report never depends on the enumerator order or on
# the host culture. Sort-Object is deliberately not used: its default string
# comparison is culture-aware and would order non-ASCII names by their base
# letter (e.g. 'Ä' and 'ö' before ASCII 'Z'), producing a different report on
# a differently configured host. Keys are compared with the ordinal,
# case-insensitive-then-case-sensitive rule of Compare-WReparsePath.
function Sort-WReparseStable {
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][object[]]$Items,
        [Parameter(Mandatory = $true)][scriptblock]$KeySelector,
        [scriptblock]$TieBreakSelector = $null
    )
    if ($null -eq $Items -or $Items.Count -eq 0) { return @() }
    $array = @($Items)
    if ($array.Count -le 1) { return @($array) }
    $middle = [int]($array.Count / 2)
    $left = @(Sort-WReparseStable -Items @($array[0..($middle - 1)]) -KeySelector $KeySelector -TieBreakSelector $TieBreakSelector)
    $right = @(Sort-WReparseStable -Items @($array[$middle..($array.Count - 1)]) -KeySelector $KeySelector -TieBreakSelector $TieBreakSelector)
    $merged = New-Object System.Collections.ArrayList
    $i = 0
    $j = 0
    while ($i -lt $left.Count -and $j -lt $right.Count) {
        $leftKey = [string](& $KeySelector $left[$i])
        $rightKey = [string](& $KeySelector $right[$j])
        $comparison = Compare-WReparsePath -Left $leftKey -Right $rightKey
        if ($comparison -eq 0 -and $null -ne $TieBreakSelector) {
            $leftTie = [string](& $TieBreakSelector $left[$i])
            $rightTie = [string](& $TieBreakSelector $right[$j])
            $comparison = Compare-WReparsePath -Left $leftTie -Right $rightTie
        }
        if ($comparison -le 0) {
            [void]$merged.Add($left[$i]); $i++
        }
        else {
            [void]$merged.Add($right[$j]); $j++
        }
    }
    while ($i -lt $left.Count) { [void]$merged.Add($left[$i]); $i++ }
    while ($j -lt $right.Count) { [void]$merged.Add($right[$j]); $j++ }
    return @($merged.ToArray())
}

# The three kind counters are mutually exclusive and each equals the number
# of records with that Kind; their sum is the record count.
function Get-WReparseStats {
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][object[]]$Records,
        [int]$Skipped = 0,
        [int]$ErrorCount = 0
    )
    $directories = 0
    $files = 0
    $reparse = 0
    foreach ($record in @($Records)) {
        switch ($record.Kind) {
            'Directory' { $directories++ }
            'File' { $files++ }
            'ReparsePoint' { $reparse++ }
        }
    }
    return New-WReparseStats -Directories $directories -Files $files -ReparsePoints $reparse `
        -Skipped $Skipped -Errors $ErrorCount
}

function Get-WReparseReport {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )
    $followMode = if ($Follow) { 'Always' } else { 'Never' }
    $walk = Invoke-WReparseWalk -Root $Root -FollowMode $followMode -MaxDepth $MaxDepth
    $records = @(Sort-WReparseStable -Items $walk.Records -KeySelector { param($item) $item.RelativePath })
    $errors = @(Sort-WReparseStable -Items $walk.Errors -KeySelector { param($item) $item.RelativePath } `
        -TieBreakSelector { param($item) $item.Code })
    $stats = Get-WReparseStats -Records $records -Skipped $walk.Skipped -ErrorCount $errors.Count
    $canonicalRoot = $null
    try { $canonicalRoot = Get-WReparseCanonicalPath $Root } catch { $canonicalRoot = $Root }
    return New-WReparseReport -Root $canonicalRoot -Records $records -Errors $errors -Stats $stats
}

function ConvertTo-WReparseJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Report
    )
    return ($Report | ConvertTo-Json -Depth 12)
}

